def balanced(text):
    pairs = {')': '(', ']': '['}
    stack = []
    for ch in text:
        if ch in '([':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

print(balanced('([])'), balanced('(]'), balanced('(('))  # True False False
Push every opener; each closer must match the most recent opener; leftovers mean unbalanced.

