from functools import cache

@cache
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(80))  # 23416728348467685
The decorator stores each fib(n) the first time; later calls return it at once, so fib(80) is instant.

def fib(n, memo):
    if n in memo:
        return memo[n]
    if n < 2:
        return n
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

print(fib(80, {}))  # 23416728348467685
This is what @cache does for you: look the answer up first, store it after computing it.

