def dfs_stack(graph, start):
    visited = set()
    order = []
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        order.append(v)
        for n in sorted(graph[v], reverse=True):
            stack.append(n)
