script = [tool_reply("get_weather", '{"city": "Paris"}'), text_reply("It is 18C.")]
def scripted_model(messages):
    return script.pop(0)

print(scripted_model([])["choices"][0]["finish_reason"])  # tool_calls
print(scripted_model([])["choices"][0]["message"]["content"])  # It is 18C.
tool_reply/text_reply build canned responses; popping them in order replays a whole conversation without an API.

def one_step(model_fn, messages):
    message = model_fn(messages)["choices"][0]["message"]
    messages.append(message)
    if not message.get("tool_calls"):
        return message["content"]
    return None

def done_model(messages):
    return text_reply("Done.")

print(one_step(done_model, []))  # Done.
A text answer means the agent has finished; None here means 'tools still to run'.

def stubborn_model(messages):
    return tool_reply("get_weather", '{"city": "Paris"}')

msgs = []
print(run_agent(stubborn_model, msgs, max_steps=3))  # Stopped: too many steps
print(len(msgs))  # 6
A model can keep calling tools forever; max_steps (Boot.dev uses 20) bounds time and cost.

WORKING_DIR = "./calculator"

def call_tool(name, args):
